 * 解压数据函数
 * @param compressed_data 压缩后的数据缓冲区
 * @param compressed_len 压缩数据的长度
 * @param output_buffer 输出缓冲区
 * @param output_size 输出缓冲区的大小
 * @return 解压后的数据长度，失败返回-1
 */
int decompress_data(unsigned char *compressed_data, int compressed_len, unsigned char *output_buffer, int output_size) {
    if (!compressed_data || !output_buffer || compressed_len <= 0 || output_size <= 0) {
        return -1; // 参数错误
    }

    int output_index = 0; // 输出缓冲区的索引
    int input_index = 0;  // 压缩数据的索引

    // 简单的RLE（Run-Length Encoding）解压算法示例
    while (input_index < compressed_len && output_index < output_size) {
        // 检查是否还有足够的数据来读取长度和值
        if (input_index + 1 >= compressed_len) {
            break; // 数据不足，退出
        }

        unsigned char count = compressed_data[input_index];     // 重复次数
        unsigned char value = compressed_data[input_index + 1]; // 要重复的值
        input_index += 2; // 移动到下一个压缩单元

        // 将值重复count次写入输出缓冲区
        for (int i = 0; i < count && output_index < output_size; i++) {
            output_buffer[output_index] = value;
            output_index++;
        }
    }

    // 检查是否解压完整
    if (input_index < compressed_len) {
        // 压缩数据还有剩余，但输出缓冲区已满
        return -1; // 输出缓冲区太小
    }

    return output_index; // 返回解压后的数据长度
